from __future__ import annotations

"""
run_xgb_fixed_origin_old_features_single_full_data.py

Один самодостаточный файл для последовательного запуска всех XGB fixed-origin моделей
со старыми признаками из исходных скриптов.

Встроенные шаги:
1. daily_global
2. daily_per_cluster
3. weekly_global
4. weekly_per_cluster
5. monthly_global
6. monthly_per_cluster

Resume:
- после успешного шага создаётся marker: run_dir/_status/<step>.done;
- при перезапуске с --run-dir готовые шаги пропускаются;
- старт будет с первого шага без .done, то есть с упавшей модели;
- можно явно задать --start-from, --only, --force-rerun-step.

Full-data semantics:
- --max-optuna-rows 0 означает без ограничения строк для Optuna;
- --max-train-rows 0 означает без ограничения строк для финального обучения;
- по умолчанию оба параметра равны 0.

Признаки:
- feature engineering находится внутри встроенных старых скриптов;
- orchestrator не пересобирает признаки заново;
- rolling look-ahead заменён на fixed-origin в самих встроенных скриптах.
"""

import argparse
import base64
import csv
import json
import re
import shlex
import subprocess
import sys
import time
from pathlib import Path
from typing import Dict, List, Optional


SCRIPT_ORDER = [('daily_global', 'daily_global_fixed_origin_old_features.py'), ('daily_per_cluster', 'daily_per_cluster_fixed_origin_old_features.py'), ('weekly_global', 'weekly_global_fixed_origin_old_features.py'), ('weekly_per_cluster', 'weekly_per_cluster_fixed_origin_old_features.py'), ('monthly_global', 'monthly_global_fixed_origin_old_features.py'), ('monthly_per_cluster', 'monthly_per_cluster_fixed_origin_old_features.py')]

EMBEDDED_SCRIPTS: Dict[str, str] = {'daily_global_fixed_origin_old_features.py': '', 'daily_per_cluster_fixed_origin_old_features.py': '', 'weekly_global_fixed_origin_old_features.py': '', 'weekly_per_cluster_fixed_origin_old_features.py': '', 'monthly_global_fixed_origin_old_features.py': '', 'monthly_per_cluster_fixed_origin_old_features.py': ''}


def ts() -> str:
    return time.strftime("%Y%m%d_%H%M%S")


def log(msg: str) -> None:
    print(msg, flush=True)


def make_run_dir(out_root: str, run_dir: Optional[str]) -> Path:
    if run_dir:
        p = Path(run_dir)
        p.mkdir(parents=True, exist_ok=True)
        return p

    p = Path(out_root) / f"run_{ts()}"
    p.mkdir(parents=True, exist_ok=True)
    return p


def write_embedded_scripts(run_dir: Path) -> Path:
    scripts_dir = run_dir / "_embedded_scripts"
    scripts_dir.mkdir(parents=True, exist_ok=True)

    for fname, b64 in EMBEDDED_SCRIPTS.items():
        path = scripts_dir / fname
        data = base64.b64decode(b64.encode("ascii"))
        path.write_bytes(data)

    return scripts_dir


def parse_csv_list(x: Optional[str]) -> Optional[List[str]]:
    if x is None or str(x).strip() == "":
        return None
    return [i.strip() for i in str(x).split(",") if i.strip()]


def build_common_args(args: argparse.Namespace, step_out: Path) -> List[str]:
    cmd = [
        "--prices-csv", args.prices_csv,
        "--future-prices-csv", args.future_prices_csv,
        "--eval-end-date", args.eval_end_date,
        "--macro-known-until", args.macro_known_until,
        "--macro-dir", args.macro_dir,
        "--cluster-csv", args.cluster_csv,
        "--season-dir", args.season_dir,
        "--out-root", str(step_out),
        "--price-col", args.price_col,
        "--n-trials", str(args.n_trials),
        "--n-jobs", str(args.n_jobs),
        "--numba-threads", str(args.numba_threads),
        "--use-gpu", str(args.use_gpu),
        "--gpu-id", str(args.gpu_id),
        "--max-optuna-rows", str(args.max_optuna_rows),
        "--max-train-rows", str(args.max_train_rows),
    ]

    if args.optuna_timeout is not None:
        cmd += ["--optuna-timeout", str(args.optuna_timeout)]

    if args.early_stopping_rounds is not None:
        cmd += ["--early-stopping-rounds", str(args.early_stopping_rounds)]

    if args.random_state is not None:
        cmd += ["--random-state", str(args.random_state)]

    if args.joblib_batch_size is not None:
        cmd += ["--joblib-batch-size", str(args.joblib_batch_size)]

    return cmd


def step_specific_args(step: str, args: argparse.Namespace) -> List[str]:
    extra: List[str] = []

    if step.startswith("daily"):
        extra += [
            "--eval-months", str(args.eval_months),
            "--forecast-horizon", str(args.forecast_horizon),
            "--short-horizon-days", str(args.short_horizon_days),
        ]
    elif step.startswith("weekly"):
        extra += [
            "--eval-years", str(args.eval_years),
            "--forecast-horizon-weeks", str(args.forecast_horizon_weeks),
            "--short-horizon-weeks", str(args.short_horizon_weeks),
        ]
    elif step.startswith("monthly"):
        extra += [
            "--eval-years", str(args.eval_years),
            "--forecast-horizon-months", str(args.forecast_horizon_months),
            "--short-horizon-months", str(args.short_horizon_months),
        ]

    if "_per_cluster" in step:
        if args.cluster_ids:
            extra += ["--cluster-ids", args.cluster_ids]
        if args.include_noise_cluster is not None:
            extra += ["--include-noise-cluster", str(args.include_noise_cluster)]

        if step.startswith("daily"):
            extra += [
                "--min-train-rows-per-cluster", str(args.min_train_rows_per_cluster),
                "--min-valid-rows-per-cluster", str(args.min_valid_rows_per_cluster),
                "--min-test-rows-per-cluster", str(args.min_test_rows_per_cluster),
            ]
        else:
            extra += [
                "--min-train-pairs-per-cluster", str(args.min_train_pairs_per_cluster),
                "--min-valid-pairs-per-cluster", str(args.min_valid_pairs_per_cluster),
                "--min-test-pairs-per-cluster", str(args.min_test_pairs_per_cluster),
            ]

    return extra


def filter_args_for_existing_parser(script_path: Path, cmd_args: List[str]) -> List[str]:
    text = script_path.read_text(encoding="utf-8", errors="ignore")

    supported = set()
    for m in re.finditer(r"add_argument\(\s*['\"](--[A-Za-z0-9_-]+)['\"]", text):
        supported.add(m.group(1))

    out: List[str] = []
    i = 0

    while i < len(cmd_args):
        a = cmd_args[i]

        if a.startswith("--"):
            has_value = i + 1 < len(cmd_args) and not cmd_args[i + 1].startswith("--")

            if a not in supported:
                if has_value:
                    i += 2
                else:
                    i += 1
                continue

            out.append(a)
            if has_value:
                out.append(cmd_args[i + 1])
                i += 2
            else:
                i += 1
        else:
            out.append(a)
            i += 1

    return out


def already_done(status_dir: Path, step: str, step_out: Path) -> bool:
    marker = status_dir / f"{step}.done"
    if not marker.exists():
        return False
    return True


def run_step(
    step: str,
    script_name: str,
    scripts_dir: Path,
    run_dir: Path,
    args: argparse.Namespace,
) -> None:
    status_dir = run_dir / "_status"
    status_dir.mkdir(parents=True, exist_ok=True)

    step_out = run_dir / step
    step_out.mkdir(parents=True, exist_ok=True)

    failed_marker = status_dir / f"{step}.failed"
    done_marker = status_dir / f"{step}.done"

    if args.force_rerun_step == step:
        for p in [done_marker, failed_marker]:
            if p.exists():
                p.unlink()

    if already_done(status_dir, step, step_out):
        log(f"[SKIP] {step} already done")
        return

    script_path = scripts_dir / script_name

    cmd_args = build_common_args(args, step_out)
    cmd_args += step_specific_args(step, args)

    cmd_args += ["--resume-run-dir", str(step_out)]

    cmd_args = filter_args_for_existing_parser(script_path, cmd_args)

    cmd = [sys.executable, str(script_path)] + cmd_args

    log("=" * 100)
    log(f"[RUN STEP] {step}")
    log(f"[SCRIPT] {script_path}")
    log(f"[OUT] {step_out}")
    log("[CMD] " + " ".join(shlex.quote(x) for x in cmd))
    log("=" * 100)

    if failed_marker.exists():
        failed_marker.unlink()

    start = time.time()
    proc = subprocess.run(cmd, cwd=str(Path.cwd()))
    elapsed = time.time() - start

    if proc.returncode != 0:
        failed_marker.write_text(
            json.dumps(
                {
                    "step": step,
                    "returncode": proc.returncode,
                    "elapsed_sec": elapsed,
                    "script": script_name,
                    "out_dir": str(step_out),
                    "cmd": cmd,
                    "failed_at": time.strftime("%Y-%m-%d %H:%M:%S"),
                },
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )

        raise SystemExit(
            f"[FAILED] step={step}, returncode={proc.returncode}. "
            f"Resume with: --run-dir {run_dir}"
        )

    done_marker.write_text(
        json.dumps(
            {
                "step": step,
                "returncode": 0,
                "elapsed_sec": elapsed,
                "script": script_name,
                "out_dir": str(step_out),
                "cmd": cmd,
                "finished_at": time.strftime("%Y-%m-%d %H:%M:%S"),
            },
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    log(f"[DONE STEP] {step}, elapsed={elapsed / 60:.2f} min")


def collect_summary(run_dir: Path) -> None:
    rows = []

    for step, _ in SCRIPT_ORDER:
        step_out = run_dir / step
        for p in step_out.glob("fixed_origin_*_metrics_overall.json"):
            try:
                row = json.loads(p.read_text(encoding="utf-8"))
                row["step"] = step
                row["metrics_file"] = str(p)
                rows.append(row)
            except Exception:
                pass

    if not rows:
        return

    keys = sorted({k for r in rows for k in r.keys()})
    out = run_dir / "fixed_origin_metrics_all_models.csv"

    with out.open("w", encoding="utf-8", newline="") as f:
        w = csv.DictWriter(f, fieldnames=keys)
        w.writeheader()
        for r in rows:
            w.writerow(r)

    log(f"[SUMMARY] {out}")


def main() -> None:
    ap = argparse.ArgumentParser("Single-file XGB fixed-origin old-features runner")

    ap.add_argument("--out-root", default="results_xgb_old_features_fixed_origin")
    ap.add_argument("--run-dir", default=None, help="Existing run dir for resume. If omitted, creates new run.")
    ap.add_argument("--start-from", default=None, choices=[s for s, _ in SCRIPT_ORDER])
    ap.add_argument("--only", default=None, help="Comma-separated steps to run, e.g. daily_global,monthly_per_cluster")
    ap.add_argument("--force-rerun-step", default=None, choices=[s for s, _ in SCRIPT_ORDER])

    ap.add_argument("--prices-csv", default="data/prices_all.csv")
    ap.add_argument("--future-prices-csv", default="data/prices_all_2025_12_20_today.csv")
    ap.add_argument("--eval-end-date", default="2026-05-08")
    ap.add_argument("--macro-known-until", default="2025-12-20")
    ap.add_argument("--macro-dir", default="data")
    ap.add_argument("--cluster-csv", default="cluster_fullstart_assignments.csv")
    ap.add_argument("--season-dir", default="results_stocks/prices_all")
    ap.add_argument("--price-col", default="Close")

    ap.add_argument("--eval-months", type=int, default=1)
    ap.add_argument("--eval-years", type=int, default=1)

    ap.add_argument("--forecast-horizon", type=int, default=21)
    ap.add_argument("--forecast-horizon-weeks", type=int, default=52)
    ap.add_argument("--forecast-horizon-months", type=int, default=12)

    ap.add_argument("--short-horizon-days", type=int, default=5)
    ap.add_argument("--short-horizon-weeks", type=int, default=13)
    ap.add_argument("--short-horizon-months", type=int, default=3)

    ap.add_argument("--n-trials", type=int, default=300)
    ap.add_argument("--optuna-timeout", type=int, default=None)
    ap.add_argument("--early-stopping-rounds", type=int, default=None)
    ap.add_argument("--random-state", type=int, default=None)

    ap.add_argument("--n-jobs", type=int, default=16)
    ap.add_argument("--numba-threads", type=int, default=16)
    ap.add_argument("--joblib-batch-size", type=int, default=None)
    ap.add_argument("--use-gpu", type=int, default=1)
    ap.add_argument("--gpu-id", type=int, default=0)

    ap.add_argument("--max-optuna-rows", type=int, default=0, help="0 means no row limit")
    ap.add_argument("--max-train-rows", type=int, default=0, help="0 means no row limit")

    ap.add_argument("--cluster-ids", default=None)
    ap.add_argument("--include-noise-cluster", type=int, default=1)

    ap.add_argument("--min-train-rows-per-cluster", type=int, default=5000)
    ap.add_argument("--min-valid-rows-per-cluster", type=int, default=500)
    ap.add_argument("--min-test-rows-per-cluster", type=int, default=500)

    ap.add_argument("--min-train-pairs-per-cluster", type=int, default=3000)
    ap.add_argument("--min-valid-pairs-per-cluster", type=int, default=300)
    ap.add_argument("--min-test-pairs-per-cluster", type=int, default=300)

    args = ap.parse_args()

    run_dir = make_run_dir(args.out_root, args.run_dir)
    scripts_dir = write_embedded_scripts(run_dir)

    (run_dir / "single_runner_config.json").write_text(
        json.dumps(vars(args), ensure_ascii=False, indent=2),
        encoding="utf-8",
    )

    selected = SCRIPT_ORDER.copy()

    only = parse_csv_list(args.only)
    if only is not None:
        allowed = set(only)
        selected = [(s, f) for s, f in selected if s in allowed]

    if args.start_from:
        names = [s for s, _ in selected]
        if args.start_from in names:
            idx = names.index(args.start_from)
            selected = selected[idx:]
        else:
            selected = []

    log("=" * 100)
    log("[RUN] SINGLE FILE XGB FIXED-ORIGIN OLD FEATURES")
    log(f"[RUN_DIR] {run_dir.resolve()}")
    log("[STEPS] " + ", ".join(s for s, _ in selected))
    log(f"[ROW LIMITS] max_optuna_rows={args.max_optuna_rows}, max_train_rows={args.max_train_rows}; 0 means full data")
    log("=" * 100)

    for step, script_name in selected:
        run_step(step, script_name, scripts_dir, run_dir, args)

    collect_summary(run_dir)

    log("\n[DONE]")
    log(f"Results: {run_dir.resolve()}")


if __name__ == "__main__":
    main()
